atts.custom_css:
selector,selector:hover{color:rgb(28, 20, 13) !important;}
selector{text-transform:uppercase !important;letter-spacing:2.8px !important;font-size:10px !important;font-weight:400 !important;padding:0px 20px 0px 20px !important;}
selector{align-self:flex-start;width:auto;}
:where(selector){background-image:linear-gradient(rgba(227, 178, 104, 0.88), rgba(183, 122, 59, 0.82)), linear-gradient(135deg, rgba(255, 255, 255, 0.08), rgba(0, 0, 0, 0) 45%);line-height:15px;text-align:center;transition:transform 0.45s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.45s;}
